ALTER TABLE public.employes ADD COLUMN est_chef_equipe_terrain boolean NOT NULL DEFAULT false;
ALTER TABLE public.dispos_intervenants ADD COLUMN est_chef_equipe_terrain boolean NOT NULL DEFAULT false, ADD COLUMN poste_terrain text, ADD COLUMN statut_terrain text, ADD COLUMN email_terrain text;
CREATE UNIQUE INDEX dispos_intervenants_employe_unique ON public.dispos_intervenants(employe_id) WHERE employe_id IS NOT NULL;
ALTER TABLE public.affaire_etapes_logistiques ADD COLUMN nb_chefs_equipe smallint NOT NULL DEFAULT 0 CHECK(nb_chefs_equipe>=0), ADD COLUMN besoins_postes jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(besoins_postes)='object'), ADD COLUMN permis_requis text[] NOT NULL DEFAULT '{}' CHECK(permis_requis <@ ARRAY['B','C','CE']::text[]), ADD COLUMN caces_requis text[] NOT NULL DEFAULT '{}' CHECK(caces_requis <@ ARRAY['R489','R486','autre']::text[]), ADD COLUMN caces_autre_requis text;
ALTER TABLE public.assignations ADD COLUMN etape_logistique_id uuid REFERENCES public.affaire_etapes_logistiques(id) ON DELETE RESTRICT, ADD COLUMN dispos_intervenant_id uuid REFERENCES public.dispos_intervenants(id) ON DELETE RESTRICT, ADD COLUMN terrain boolean NOT NULL DEFAULT false, ADD COLUMN historique_terrain boolean NOT NULL DEFAULT false, ADD COLUMN validation_logistique text NOT NULL DEFAULT 'valide' CHECK(validation_logistique IN ('propose','valide')), ADD COLUMN source_terrain text CHECK(source_terrain IS NULL OR source_terrain IN ('manuelle','historique_consolide','suggestion')), ADD COLUMN role_terrain text NOT NULL DEFAULT 'equipier' CHECK(role_terrain IN ('chef_equipe','equipier')), ADD COLUMN fin_jour_suivant boolean NOT NULL DEFAULT false, ADD COLUMN provenance_terrain jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE INDEX assignations_etape_logistique ON public.assignations(etape_logistique_id,date);
CREATE UNIQUE INDEX assignations_historique_unique ON public.assignations(affaire_id,date,employe_id) WHERE historique_terrain AND employe_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.planning_terrain_lire_autorise() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (has_role(auth.uid(),'admin') OR has_role(auth.uid(),'logistique') OR has_role(auth.uid(),'chef_chantier')) $$;
CREATE OR REPLACE FUNCTION public.planning_terrain_ecrire_autorise() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (auth.jwt()->>'client_id') IS NULL AND (has_role(auth.uid(),'admin') OR has_role(auth.uid(),'logistique')) $$;
REVOKE ALL ON FUNCTION public.planning_terrain_lire_autorise(),public.planning_terrain_ecrire_autorise() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.planning_terrain_lire_autorise(),public.planning_terrain_ecrire_autorise() TO authenticated;
CREATE POLICY terrain_select ON public.assignations FOR SELECT TO authenticated USING (terrain AND public.planning_terrain_lire_autorise());
CREATE POLICY terrain_insert ON public.assignations FOR INSERT TO authenticated WITH CHECK (terrain AND public.planning_terrain_ecrire_autorise());
CREATE POLICY terrain_update ON public.assignations FOR UPDATE TO authenticated USING (terrain AND public.planning_terrain_ecrire_autorise()) WITH CHECK (terrain AND public.planning_terrain_ecrire_autorise());
CREATE POLICY terrain_restrict_insert ON public.assignations AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (NOT terrain OR public.planning_terrain_ecrire_autorise());
CREATE POLICY terrain_restrict_update ON public.assignations AS RESTRICTIVE FOR UPDATE TO authenticated USING (NOT terrain OR public.planning_terrain_ecrire_autorise()) WITH CHECK (NOT terrain OR public.planning_terrain_ecrire_autorise());
CREATE POLICY terrain_restrict_delete ON public.assignations AS RESTRICTIVE FOR DELETE TO authenticated USING (NOT terrain OR public.planning_terrain_ecrire_autorise());
CREATE POLICY terrain_restrict_select ON public.assignations AS RESTRICTIVE FOR SELECT TO authenticated USING (NOT terrain OR public.planning_terrain_lire_autorise());
COMMENT ON COLUMN public.assignations.historique_terrain IS 'Passage consolidé sans durée connue : exclure des volumes horaires et occupations.';